("heterogeneous","GREEK ORIGIN",[("hetero-","different","不同的","two different shapes"),("genos","kind, type","種類","sorted boxes of types")],("of different kinds → mixed","由不同成分組成的；混雜的"),"a big salad bowl full of very different things: fruit, vegetables, nuts, and noodles, with each piece a different shape and color.","Many kinds all mixed in one,","Heterogeneous salad, lots of fun."),
("pittance","OLD FRENCH ORIGIN",[("pietas","pity, mercy","憐憫","a heart with a tear"),("pitance","a small allowance of food given out of pity","出於憐憫的少量配給","a tiny bowl of soup")],("a tiny amount given out of pity → very little money","微薄的收入；少量的錢"),"a boy finishes washing a huge pile of dishes and receives just one tiny coin; he stares at it with a sad face.","Hours of work for one small coin,","A pittance makes you want to groan."),
("glib","LOW GERMAN ORIGIN",[("glibberig","slippery","滑溜的","a slippery banana peel"),("-","smooth-talking","說話圓滑","a smooth flowing speech bubble")],("slippery and smooth → easy talk without sincerity","油嘴滑舌的；圓滑而膚淺的"),"a salesman with a shiny smile slides words out like slippery soap bubbles to a doubtful customer; one bubble pops to show nothing inside.","Slippery words that slide with ease,","Glib talk tries too hard to please."),
("penchant","FRENCH ORIGIN",[("pendere","to hang, weigh","懸掛、秤重","a hanging weight"),("pencher","to lean, incline","傾斜","a leaning tower")],("leaning toward something → a strong liking","嗜好；傾向"),"a girl's whole body leans toward a bakery window full of chocolate cakes, like a leaning tower, while her friend pulls her arm.","Always leaning toward the treat,","A penchant for things that are sweet."),
("solicitous","LATIN ORIGIN",[("sollus","whole, entirely","完全的","a full circle"),("citus","set in motion, stirred","被激起、攪動","a stirring spoon swirl")],("wholly stirred up with worry → caring and concerned","關切的；體貼的"),"a girl gently brings her sick friend a blanket, soup, and tissues, worried hearts floating above her head.","Fully stirred with gentle care,","Solicitous friends are always there."),
("circumscribe","LATIN ORIGIN",[("circum-","around","周圍","a circle arrow"),("scribere","to write, draw","寫、畫","a pencil")],("draw a line around → limit","限制；約束"),"a teacher draws a chalk circle around a playground area; kids must stay inside the line while a ball rolls outside.","Draw a line all around,","Circumscribe the playground."),
